function flyerSvg(business,product,copy){const words=String(copy||"").split(/\s+/);const lines=[];let line="";for(const word of words){if((line+" "+word).trim().length>36){if(line)lines.push(line);line=word}else line=(line+" "+word).trim()}if(line)lines.push(line);const body=lines.slice(0,7).map((v,i)=>`<text x="58" y="${430+i*38}" font-family="Arial,sans-serif" font-size="23" fill="#183b2c">${xmlEscape(v)}</text>`).join("");return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#eff9f1"/><stop offset="1" stop-color="#ccebd5"/></linearGradient><linearGradient id="hero" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#164b32"/><stop offset="1" stop-color="#287b4c"/></linearGradient></defs><rect width="1080" height="1350" fill="url(#bg)"/><circle cx="980" cy="120" r="260" fill="#b5dfc2" opacity=".5"/><rect x="48" y="48" width="984" height="1254" rx="42" fill="#fff" opacity=".92"/><rect x="48" y="48" width="984" height="360" rx="42" fill="url(#hero)"/><text x="88" y="130" font-family="Arial,sans-serif" font-size="26" font-weight="700" fill="#d5f2dd">${xmlEscape(business?.name||"Your Business").slice(0,48)}</text><text x="88" y="250" font-family="Arial,sans-serif" font-size="64" font-weight="800" fill="#fff">SPECIAL OFFER</text><text x="88" y="330" font-family="Arial,sans-serif" font-size="30" fill="#d8f2df">SHOP SMART · BUY WITH CONFIDENCE</text><text x="58" y="490" font-family="Arial,sans-serif" font-size="48" font-weight="800" fill="#164b32">${xmlEscape(product||"Featured Product").slice(0,40)}</text>${body}<rect x="58" y="800" width="964" height="170" rx="28" fill="#e7f5eb"/><text x="94" y="870" font-family="Arial,sans-serif" font-size="30" font-weight="700" fill="#164b32">ORDER TODAY</text><text x="94" y="925" font-family="Arial,sans-serif" font-size="25" fill="#355d43">${xmlEscape(business?.phone||business?.whatsapp_number||"Contact us for details").slice(0,60)}</text><text x="58" y="1090" font-family="Arial,sans-serif" font-size="22" fill="#718176">Made with BizPilot AI Marketing</text><text x="58" y="1170" font-family="Arial,sans-serif" font-size="28" font-weight="700" fill="#164b32">${xmlEscape(business?.instagram_handle||business?.facebook_handle||"")}</text></svg>`}

function PublicShop({slug}) {
 const [data,setData]=useState(null),[cart,setCart]=useState({}),[customer,setCustomer]=useState({name:"",phone:"",email:"",address:"",note:""}),[busy,setBusy]=useState(false),[message,setMessage]=useState("");
 const endpoint=SUPABASE_URL.replace(/\/$/,"")+"/functions/v1/public-store";
 useEffect(()=>{fetch(endpoint+"?slug="+encodeURIComponent(slug)).then(r=>r.json()).then(setData).catch(()=>setMessage("Could not load this shop."))},[slug]);
 const items=Object.entries(cart).filter(([,q])=>q>0).map(([id,q])=>({product_id:id,quantity:q}));
 const total=(data?.products||[]).reduce((s,p)=>s+(cart[p.id]||0)*Number(p.price_kobo),0);
 async function order(e){e.preventDefault();setBusy(true);setMessage("");try{const r=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({slug,customer_name:customer.name,customer_phone:customer.phone,customer_email:customer.email,delivery_address:customer.address,customer_note:customer.note,items})});const j=await r.json();if(!r.ok)throw new Error(j.error||"Order failed");setCart({});setMessage("Order received! Your order number is "+j.order.order_number+". The shop owner will contact you.");}catch(e){setMessage(e.message)}finally{setBusy(false)}}
 if(!data?.shop)return <div className="public-shop"><h1>BizPilot shop</h1><p>{message||"Loading shop…"}</p></div>;
 return <div className="public-shop"><header><div className="store-logo">{data.shop.name?.slice(0,1)}</div><div><h1>{data.shop.name}</h1><p>{data.shop.business_description}</p></div></header><h2>Shop products</h2><div className="public-products">{data.products.map(p=><article key={p.id}>{p.image_url?<img src={p.image_url} alt={p.name}/>:<div className="product-icon"><Package/></div>}<b>{p.name}</b><small>{p.description||p.category}</small><strong>{money(p.price_kobo)}</strong><div className="cart-controls"><button onClick={()=>setCart(c=>({...c,[p.id]:Math.max(0,(c[p.id]||0)-1)}))}>−</button><span>{cart[p.id]||0}</span><button disabled={(cart[p.id]||0)>=p.quantity} onClick={()=>setCart(c=>({...c,[p.id]:(c[p.id]||0)+1}))}>+</button></div><small>{p.quantity} available</small></article>)}</div>{items.length>0&&<form className="public-order" onSubmit={order}><h2>Your order · {money(total)}</h2><label>Full name<input required value={customer.name} onChange={e=>setCustomer({...customer,name:e.target.value})}/></label><label>Phone number<input required value={customer.phone} onChange={e=>setCustomer({...customer,phone:e.target.value})}/></label><label>Email (optional)<input type="email" value={customer.email} onChange={e=>setCustomer({...customer,email:e.target.value})}/></label><label>Delivery address<input value={customer.address} onChange={e=>setCustomer({...customer,address:e.target.value})}/></label><label>Order note<textarea value={customer.note} onChange={e=>setCustomer({...customer,note:e.target.value})}/></label><button className="primary" disabled={busy}>{busy?"Submitting…":"Place order"}</button></form>}{message&&<p className="notice">{message}</p>}<footer>Powered by BizPilot</footer></div>;
}

